/bin/bash -lc "cat > src/util/checkoutRequest.mjs <<'EOF'
/**
 * Builds the checkout request the storefront POSTs to the backend.
 *
 * The path and body field names mirror what src/pages/other/Checkout.js
 * sends to "'`cart/<cartCode>/checkout` (shippingQuote, currency, payment
 * with paymentType/transactionType/paymentModule/paymentToken/amount).
 */
export function buildCheckoutRequest({
  cartCode,
  shippingOptionId,
  currency,
  paymentToken,
  paymentModule,
  amount,
  agreedToTerms,
  comments,
}) {
  const path = `cart/${cartCode}/checkout`;

  const body = {
    shippingQuote: shippingOptionId,
    currency,
    agreedToTerms: Boolean(agreedToTerms),
    comments,
    payment: {
      paymentType: "CREDITCARD",
      transactionType: "CAPTURE",
      paymentModule,
      paymentToken,
      amount,
    },
  };

  return { method: "POST", path, body };
}

export default buildCheckoutRequest;
EOF
node --check src/util/checkoutRequest.mjs && echo OK'
